INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто вправе постановлением предоставить сотрудникам СК, прокуратуры, ФСБ право проникновения на закрытую территорию для задержания? Выберите все верные.', '[{"id":"tWcLEvt2","text":"Начальник управления ФСБ по региону"},{"id":"dcw5ruu2","text":"Директор ФСБ или уполномоченное им должностное лицо Центрального аппарата ФСБ"},{"id":"rTSSKtHT","text":"Руководитель следственного органа СК России"},{"id":"Qf9N4TRR","text":"Прокурор"},{"id":"VQVALri8","text":"Командир воинской части, на территории которой производится задержание"},{"id":"ssc2HxY","text":"Губернатор Федерального округа Российской Федерации"},{"id":"TRygXApi","text":"Министр обороны Российской Федерации"}]', '["tWcLEvt2","dcw5ruu2","rTSSKtHT","Qf9N4TRR"]', '', 3, 20010, '{"meta":{"article":"Статья 13, ч. 13.9","explanation":"ПК, ст. 13, ч. 13.9: право предоставить проникновение на закрытую территорию для задержания имеют начальник управления ФСБ по региону, Директор ФСБ или уполномоченное им должностное лицо Центрального аппарата ФСБ, руководитель следственного органа СК России и прокурор. Командир части, губернатор и министр обороны в этой норме не названы. (ред. с форума, 12.11.2026)","quote":"Начальник управления Федеральной службой безопасности по региону, Директор Федеральной службы безопасности или уполномоченное им должностное лицо Центрального аппарата Федеральной службы безопасности, руководитель следственного органа Следственного комитета России, прокурор вправе предоставить право на проникновение на закрытую территорию","difficulty":"3"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q046~v2', NULL, 'full', 3, 'pk', 'Статья 13, ч. 13.9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q046~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто вправе проходить, проезжать и иным методом проникать на все закрытые и охраняемые территории по общему правилу закона (кроме случаев, установленных законом)? Выберите все верные.', '[{"id":"YfKceGjF","text":"Министры Федерального округа и их заместители по любым вопросам"},{"id":"y65JzPC","text":"Любые сотрудники ФСО без сопровождения"},{"id":"ApiV4xvn","text":"Губернатор ФО, Председатель Совета Федерации, Председатель законодательного собрания ФО"},{"id":"65VcxlMQ","text":"Генеральный прокурор РФ, его заместители и их помощники"},{"id":"GnkYiQHi","text":"Сотрудники ГБУЗ при любой цели визита"},{"id":"FaH5uQyL","text":"Прокуроры субъектов РФ и их заместители"},{"id":"rXAHyK2W","text":"Судьи РФ"},{"id":"KmsIBlbW","text":"Директор Федеральной службы безопасности и его заместители"}]', '["ApiV4xvn","65VcxlMQ","FaH5uQyL","rXAHyK2W","KmsIBlbW"]', '', 3, 20020, '{"meta":{"article":"Статья 4, ч. 4.1","explanation":"86-ФЗ, ст. 4, ч. 4.1: такое право имеют Губернатор ФО, Председатель Совета Федерации, Председатель законодательного собрания ФО, а также наделённые теми же правами Вице-губернатор, Директор ФСБ и его заместители, судьи РФ, Генеральный прокурор и его заместители и помощники, Председатель СК и его заместители и помощники, прокуроры субъектов и их заместители и другие указанные в части лица. Министры — только на закреплённые территории (ч. 4.2); сотрудники ФСО — в сопровождении (ч. 4.5); медики — с целью медпомощи (ч. 4.6). (ред. с форума, 12.11.2026)","quote":"Губернатор Федерального округа Российской Федерации, Председатель Совета Федерации, Председатель законодательного собрания Федерального округа имеют право проходить, проезжать и иным методом проникать на все закрытые и охраняемые территории … Директор Федеральной службы безопасности и его заместители","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_territorii-q007~v3', NULL, 'vp', 3, 'fz_territorii', 'Статья 4, ч. 4.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q007~v3');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: На КПП В/Ч прибывает помощник Генерального прокурора без пропуска и заявляет о проведении надзорного мероприятия. Дежурный требует оформить разовый пропуск.

Вопрос: Прав ли дежурный?', '[]', '[]', 'По ч. 4.1 Генеральный прокурор, его заместители и их помощники имеют право проходить, проезжать и иным методом проникать на все закрытые и охраняемые территории, кроме случаев, предусмотренных законом; по ч. 30.2 лица ст. 4 имеют доступ к территориям с пропускным режимом без пропуска. Однако ч. 4.4 указывает, что иной порядок входа на закрытую территорию войсковых частей в рамках надзорных мероприятий установлен ст. 21 (допуск по пропускному режиму, ч. 21.3). Поэтому дежурный действует по пропускному режиму части, но обязан учесть статус помощника ГП; спорное место — соотношение ч. 4.1/30.2 и ч. 4.4/21.3.', 10, 20030, '{"meta":{"article":"Статья 4, ч. 4.1, 4.4; Статья 21, ч. 21.3; Статья 30, ч. 30.2","difficulty":"2"},"criteria":[{"text":"Статус помощника ГП по ч. 4.1","points":2},{"text":"Ч. 30.2 — без пропуска","points":2},{"text":"Особый порядок для В/Ч по ч. 4.4 → ст. 21","points":4},{"text":"Аргументированный вывод","points":2}]}', 'Переаттестация: Общие кейсы', 'case', 0, 1, 'r6-fz_territorii-c02~v2', NULL, 'cases_gen', 2, 'fz_territorii', 'Статья 4, ч. 4.1, 4.4; Статья 21, ч. 21.3; Статья 30, ч. 30.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-c02~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие органы и должностные лица способны относить сведения к государственной тайне и присваивать гриф секретности?', '[{"id":"FBgyDIVp","text":"Командир бригады"},{"id":"dtpuVXw","text":"Директор ФСБ и начальники региональных управлений ФСБ"},{"id":"G0l9SFfR","text":"Начальник управления ФСО"},{"id":"peWWSSrx","text":"Министр внутренних дел Федерального округа"},{"id":"j8kAuu6","text":"Министр обороны Федерального округа"},{"id":"JT1ihzmo","text":"Губернатор Федерального округа РФ"},{"id":"49iNIYTa","text":"Прокуроры субъектов РФ"}]', '["dtpuVXw","G0l9SFfR","JT1ihzmo","49iNIYTa"]', '', 3, 20040, '{"meta":{"article":"Статья 3","explanation":"ФЗ «О государственной тайне», ст. 3: к органам и должностям, способным относить сведения к гостайне и присваивать гриф, относятся в том числе Губернатор ФО, прокуроры субъектов, Директор ФСБ и начальники региональных управлений ФСБ, начальник управления ФСО. Командир бригады, министр внутренних дел и министр обороны ФО в перечне не названы. (ред. с форума, 12.11.2026)","quote":"7) Директор Федеральной службы безопасности Российской Федерации и Начальники региональных управлений Федеральной службы безопасности Российской Федерации.","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_gostayna-q005~v2', NULL, 'vp', 3, 'fz_gostayna', 'Статья 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q005~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто исключительно может произвести рассекречивание сведений, составляющих государственную тайну, в пределах своей компетенции? Выберите все верные.', '[{"id":"j5FSQJdm","text":"Президент Российской Федерации"},{"id":"0P2eYl","text":"Губернатор Федерального округа Российской Федерации"},{"id":"1YJXZ9t","text":"Директор ФСБ — по сведениям, отнесённым к гостайне органами ФСБ"},{"id":"hZrSN1j6","text":"Верховный суд Российской Федерации"},{"id":"HGZV0ft","text":"Конституционный суд Российской Федерации"},{"id":"1qZK97uK","text":"Генеральный прокурор Российской Федерации"},{"id":"QQCeNJfy","text":"Начальник регионального управления ФСБ"}]', '["j5FSQJdm","0P2eYl","1YJXZ9t"]', '', 3, 20050, '{"meta":{"article":"Статья 8, ч. 8.2","explanation":"ФЗ «О государственной тайне», ст. 8, ч. 8.2: рассекречивание производится исключительно Президентом РФ, Губернатором ФО и Директором ФСБ — в отношении сведений, отнесённых к гостайне органами ФСБ, в пределах их компетенции. Верховный и Конституционный суды, Генеральный прокурор и начальник регионального управления ФСБ в этот перечень больше не входят. (ред. с форума, 12.11.2026)","quote":"Рассекречивание сведений, составляющих государственную тайну, может быть произведено исключительно следующими органами государственной власти и должностными лицами в пределах их компетенции: … 1) Президент Российской Федерации; … 2) Губернатор Федерального округа Российской Федерации; … 3) Директор Федеральной службы безопасности Российской Федерации — в отношении сведений, отнесенных к государственной тайне органами Федеральной службы безопасности.","difficulty":"3"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gostayna-q015~v2', NULL, 'medium', 3, 'fz_gostayna', 'Статья 8, ч. 8.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q015~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие должности и подразделения включены в перечень, составляющий государственную тайну?', '[{"id":"kFQK74gV","text":"Любые военнослужащие военной полиции, несущие службу в составе патрульных нарядов и на КПП воинских частей"},{"id":"I95Warzm","text":"Третья служба по защите конституционного строя и борьбе с экстремизмом и терроризмом ФСБ и её сотрудники"},{"id":"GZxCFMYH","text":"Все сотрудники Министерства юстиции"},{"id":"KnvunKkr","text":"Сотрудники Первой и Второй оперативно-следственных служб ФСБ, выполняющие ОРМ"},{"id":"1hPsFXXH","text":"Военнослужащие Сил специальных операций в служебной форме спецподразделения с использованием средств сокрытия личности"},{"id":"H0zc5wbf","text":"Сотрудники патрульно-постовой службы полиции"},{"id":"8n0152EN","text":"Сотрудники оперативно-следственного управления Центрального аппарата ФСБ"}]', '["I95Warzm","KnvunKkr","1hPsFXXH","8n0152EN"]', '', 2, 20060, '{"meta":{"article":"Статья 9","explanation":"ФЗ «О государственной тайне», ст. 9: в перечень входят Третья служба ФСБ и её сотрудники; сотрудники Первой и Второй оперативно-следственных служб ФСБ, выполняющие ОРМ; военнослужащие ССО в форме спецподразделения со средствами сокрытия личности; сотрудники оперативно-следственного управления ЦА ФСБ. Военная полиция, Минюст и ППС в статье не названы. (ред. с форума, 12.11.2026)","quote":"4) военнослужащие подразделений Сил специальных операций, находящиеся в служебной форме специального подразделения с использованием средств сокрытия личности … 5) Сотрудники оперативно-следственного управления Центрального аппарата Федеральной Службы Безопасности.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q016~v3', NULL, 'full', 2, 'fz_gostayna', 'Статья 9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q016~v3');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'По чьему решению может быть прекращён допуск должностного лица или гражданина к государственной тайне?', '[{"id":"t8z43UYw","text":"По решению Законодательного собрания или прокурора"},{"id":"cqpdU3V","text":"По решению любого сослуживца"},{"id":"vgDjkPw","text":"Только по приговору суда"},{"id":"FAreCesB","text":"По решению руководителя государственной организации"}]', '["FAreCesB"]', '', 2, 20070, '{"meta":{"article":"Статья 14","explanation":"ФЗ «О государственной тайне», ст. 14: допуск прекращается по решению руководителя государственной организации в случаях, установленных статьёй, а также при получении заключения органов ФСБ о наличии обстоятельств, препятствующих дальнейшему допуску. Решение обжалуется в вышестоящую организацию или в суд (п. 5). (ред. с форума, 12.11.2026)","quote":"Допуск должностного лица или гражданина к государственной тайне может быть прекращен по решению руководителя государственной организации в случаях, установленных настоящей статьей, а также при получении от органов Федеральной службы безопасности заключения о наличии обстоятельств, препятствующих дальнейшему допуску к государственной тайне","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q029~v2', NULL, 'full', 2, 'fz_gostayna', 'Статья 14', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q029~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Чем определяется порядок проведения органами Федеральной службы безопасности проверок соблюдения требований по защите государственной тайны?', '[{"id":"MMbYlz","text":"Нормативными правовыми актами Директора Федеральной службы безопасности"},{"id":"pRucylIs","text":"Руководителями судебных органов и органов прокуратуры самостоятельно в каждом органе"},{"id":"RBVRps2K","text":"Постановлениями Правительства Федерального округа Российской Федерации по каждому ведомству"},{"id":"Q9USGOLY","text":"Приказами министра обороны Российской Федерации и командиров воинских частей"}]', '["MMbYlz"]', '', 3, 20080, '{"meta":{"article":"Статья 17, ч. 17.3","explanation":"ФЗ «О государственной тайне», ст. 17, ч. 17.3: порядок проверок, которые проводят органы ФСБ, определяется нормативными правовыми актами Директора ФСБ. Прежняя норма о контроле, организуемом руководителями судебных органов и прокуратуры, из этой части исключена. (ред. с форума, 12.11.2026)","quote":"Порядок проведения органами Федеральной службы безопасности проверок соблюдения требований по защите государственной тайны определяется нормативными правовыми актами Директора Федеральной службы безопасности.","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gostayna-q033~v2', NULL, 'medium', 3, 'fz_gostayna', 'Статья 17, ч. 17.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q033~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Командир войсковой части решил собственным приказом присвоить гриф «совершенно секретно» плану учений.

Вопрос: Может ли командир самостоятельно относить сведения к гостайне и присваивать гриф?', '[]', '[]', 'Перечень органов и должностей, способных к отнесению к гостайне и присвоению грифа, установлен ст. 3 (Губернатор ФО, ВС, КС, Генпрокурор и заместители, Председатель СК и заместители, прокуроры субъектов, руководители следственных органов СК, Директор ФСБ и начальники региональных управлений ФСБ, начальник управления ФСО); командир части в нём не назван. Засекречивание основывается на соответствии перечням сведений, подлежащих засекречиванию (ч. 7.2), с соблюдением принципов законности, обоснованности, своевременности (ч. 5.2). Должностные лица, принявшие решения о засекречивании, несут ответственность (ч. 5.3). Сами сведения о планах операций могут относиться к гостайне (ч. 4.1 п. 1), но гриф присваивается в установленном порядке.', 10, 20090, '{"meta":{"article":"ФЗ «О гостайне» ст. 3; ст. 4 ч. 4.1 п. 1; ст. 5 ч. 5.2, 5.3; ст. 7 ч. 7.2","difficulty":"2"},"criteria":[{"text":"Перечень ст. 3, командира нет","points":4},{"text":"Основание засекречивания ч. 7.2","points":2},{"text":"Принципы ч. 5.2 / ответственность ч. 5.3","points":2},{"text":"Отнесение планов к гостайне по ч. 4.1","points":2}]}', 'Переаттестация: Общие кейсы', 'case', 0, 1, 'r6-fz_gostayna-c02~v2', NULL, 'cases_gen', 2, 'fz_gostayna', 'ФЗ «О гостайне» ст. 3; ст. 4 ч. 4.1 п. 1; ст. 5 ч. 5.2, 5.3; ст. 7 ч. 7.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-c02~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Командир бригады хочет рассекретить старый приказ с грифом «секретно», чтобы опубликовать его к юбилею части.

Вопрос: Кто вправе рассекретить сведения?', '[]', '[]', 'Рассекречивание — снятие ранее введённых ограничений на распространение и доступ (ч. 8.1). Оно может быть произведено исключительно Президентом РФ, Губернатором ФО и Директором ФСБ — в отношении сведений, отнесённых к гостайне органами ФСБ, в пределах их компетенции (ч. 8.2). Командир бригады рассекречивать не вправе; публикация без рассекречивания повлечёт ответственность по ч. 15.1. Командиру следует обратиться по команде с ходатайством к Губернатору ФО либо учесть полномочия Директора ФСБ, если сведения отнесены органами ФСБ.', 10, 20100, '{"meta":{"article":"ФЗ «О гостайне» ст. 8; ст. 15 ч. 15.1","difficulty":"3"},"criteria":[{"text":"Определение рассекречивания","points":2},{"text":"Исчерпывающий перечень ч. 8.2: Президент РФ, Губернатор ФО, Директор ФСБ (по сведениям, отнесённым органами ФСБ)","points":5},{"text":"Ответственность / правильный путь","points":3}]}', 'Переаттестация: Общие кейсы', 'case', 0, 1, 'r6-fz_gostayna-c03~v2', NULL, 'cases_gen', 3, 'fz_gostayna', 'ФЗ «О гостайне» ст. 8; ст. 15 ч. 15.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-c03~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Прокурор субъекта присвоил гриф «секретно» материалам проверки по воинской части, а затем Генеральный прокурор решил их рассекретить. Параллельно встал вопрос, чем определяется порядок проведения органами ФСБ проверок соблюдения требований по защите гостайны.

Вопрос: Оцените полномочия по отнесению, рассекречиванию и контролю.', '[]', '[]', 'Прокуроры субъектов РФ вправе относить сведения к гостайне и присваивать гриф (ст. 3 п. 5). Рассекречивание производится исключительно Президентом РФ, Губернатором ФО и Директором ФСБ — в отношении сведений, отнесённых к гостайне органами ФСБ, в пределах их компетенции (ч. 8.2). Генеральный прокурор, хотя и вправе относить сведения к гостайне (ст. 3 п. 4), рассекретить их не вправе. Порядок проведения органами ФСБ проверок соблюдения требований по защите государственной тайны определяется нормативными правовыми актами Директора ФСБ (ч. 17.3); общий контроль за обеспечением защиты гостайны осуществляют Губернатор ФО и Правительство ФО (ст. 16).', 10, 20110, '{"meta":{"article":"ФЗ «О гостайне» ст. 3 пп. 4, 5; ст. 8 ч. 8.2; ст. 16; ст. 17 ч. 17.3","difficulty":"3"},"criteria":[{"text":"Право прокурора субъекта на гриф","points":2},{"text":"Генпрокурор не вправе рассекречивать; перечень ч. 8.2 (Президент, Губернатор, Директор ФСБ)","points":4},{"text":"Порядок проверок ФСБ — акты Директора ФСБ (ч. 17.3)","points":2},{"text":"Общий контроль ст. 16","points":2}]}', 'Переаттестация: Общие кейсы', 'case', 0, 1, 'r6-fz_gostayna-c09~v2', NULL, 'cases_gen', 3, 'fz_gostayna', 'ФЗ «О гостайне» ст. 3 пп. 4, 5; ст. 8 ч. 8.2; ст. 16; ст. 17 ч. 17.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-c09~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто вправе постановлением предоставить право на проникновение на закрытую территорию для производства задержания? Выберите все верные.', '[{"id":"HhVul3ue","text":"Командир батальона военной полиции"},{"id":"S9mklH1r","text":"Руководитель следственного органа СК России"},{"id":"DrVAnnja","text":"Начальник регионального подразделения ГИБДД"},{"id":"QGiBJTD8","text":"Военный комендант гарнизона"},{"id":"pnk0DlCk","text":"Начальник управления ФСБ по региону"},{"id":"qLxkxk5","text":"Прокурор"},{"id":"ZCYy0PgJ","text":"Директор ФСБ или уполномоченное им должностное лицо Центрального аппарата ФСБ"}]', '["S9mklH1r","pnk0DlCk","qLxkxk5","ZCYy0PgJ"]', '', 3, 20120, '{"meta":{"article":"Статья 13, ч. 13.9","explanation":"ПК, ст. 13, ч. 13.9 называет начальника управления ФСБ по региону, Директора ФСБ или уполномоченное им должностное лицо Центрального аппарата ФСБ, руководителя следственного органа СК и прокурора. Командир батальона ВП, начальник ГИБДД и военный комендант в перечень не входят. (ред. с форума, 12.11.2026)","quote":"Начальник управления Федеральной службой безопасности по региону, Директор Федеральной службы безопасности или уполномоченное им должностное лицо Центрального аппарата Федеральной службы безопасности, руководитель следственного органа Следственного комитета России, прокурор вправе предоставить право на проникновение на закрытую территорию для производства задержания","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-021~v3', 'r6-pk-proniknovenie-postanovlenie', 'vp', 3, 'pk', 'Статья 13, ч. 13.9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-021~v3');
