UPDATE reattestations SET description = 'Максимальная сложность: законодательство (включая УПК) и уставы в применении к службе Военной полиции. 30 вопросов, поровну с одним и с несколькими ответами.' WHERE key = 'full_vp' AND description IN ('Максимальная сложность: законодательство и уставы в применении к службе Военной полиции.');
